import Foundation
import XCTest
@testable import RewardsCore

/// Runs every case in shared/test-vectors (generated by shared/test-vectors/generate.py).
final class VectorTests: XCTestCase {
    private static var vectorsDir: URL {
        // .../apple/Packages/RewardsCore/Tests/RewardsCoreTests/VectorTests.swift -> repo root
        var url = URL(fileURLWithPath: #filePath)
        for _ in 0..<6 { url.deleteLastPathComponent() }
        return url.appendingPathComponent("shared/test-vectors")
    }

    private func load<T: Decodable>(_ name: String, as: T.Type) throws -> T {
        let data = try Data(contentsOf: Self.vectorsDir.appendingPathComponent(name))
        return try JSONDecoder().decode(T.self, from: data)
    }

    // MARK: Qualification

    struct QualificationFile: Decodable {
        struct Sample: Decodable {
            let name: String
            let activityType: ActivityType
            let rules: Rules
            let birthYear: Int
            let atYear: Int
            let hr: Int?
            let cadence: Double?
            let expectedThresholdBpm: Int
            let expectedPass: Bool
        }
        struct Session: Decodable {
            let name: String
            let rules: Rules
            let minutes: [MinuteResult]
            let expectedQualifyingMinutes: Int
            let expectedEarnedMinutes: Int
        }
        let samples: [Sample]
        let sessions: [Session]
    }

    func testQualificationVectors() throws {
        let file = try load("qualification.json", as: QualificationFile.self)
        XCTAssertFalse(file.samples.isEmpty)
        for c in file.samples {
            XCTAssertEqual(
                Qualification.hrThresholdBpm(rules: c.rules, activity: c.activityType, birthYear: c.birthYear, atYear: c.atYear),
                c.expectedThresholdBpm, c.name)
            XCTAssertEqual(
                Qualification.samplePasses(rules: c.rules, activity: c.activityType, birthYear: c.birthYear,
                                           atYear: c.atYear, hr: c.hr, cadence: c.cadence),
                c.expectedPass, c.name)
        }
        for c in file.sessions {
            XCTAssertEqual(Qualification.qualifyingMinutes(rules: c.rules, minutes: c.minutes),
                           c.expectedQualifyingMinutes, c.name)
            XCTAssertEqual(Qualification.earnedMinutes(rules: c.rules, minutes: c.minutes),
                           c.expectedEarnedMinutes, c.name)
        }
    }

    // MARK: Ledger

    struct LedgerFile: Decodable {
        struct Case: Decodable {
            let name: String
            let maxBank: Int?
            let entries: [LedgerEntry]
            let expectedBalance: Int
        }
        let cases: [Case]
    }

    func testLedgerVectors() throws {
        let file = try load("ledger.json", as: LedgerFile.self)
        XCTAssertFalse(file.cases.isEmpty)
        for c in file.cases {
            XCTAssertEqual(Ledger.balance(entries: c.entries, maxBank: c.maxBank), c.expectedBalance, c.name)
        }
    }

    // MARK: Status

    struct StatusFile: Decodable {
        struct Expected: Decodable {
            let balance: Int
            let todayPlayed: Int
            let minutesAvailable: Int
            let canPlay: Bool
            let reason: PlayBlockReason?
        }
        struct Case: Decodable {
            let name: String
            let rules: Rules
            let timeZone: String
            let now: String
            let entries: [LedgerEntry]
            let expected: Expected
        }
        let cases: [Case]
    }

    func testStatusVectors() throws {
        let file = try load("status.json", as: StatusFile.self)
        XCTAssertFalse(file.cases.isEmpty)
        let iso = ISO8601DateFormatter()
        for c in file.cases {
            let tz = try XCTUnwrap(TimeZone(identifier: c.timeZone), c.name)
            let now = try XCTUnwrap(iso.date(from: c.now), c.name)
            let s = PlayStatus.compute(rules: c.rules, timeZone: tz, now: now, entries: c.entries)
            XCTAssertEqual(s.balance, c.expected.balance, "\(c.name): balance")
            XCTAssertEqual(s.todayPlayed, c.expected.todayPlayed, "\(c.name): todayPlayed")
            XCTAssertEqual(s.minutesAvailable, c.expected.minutesAvailable, "\(c.name): minutesAvailable")
            XCTAssertEqual(s.canPlay, c.expected.canPlay, "\(c.name): canPlay")
            XCTAssertEqual(s.reason, c.expected.reason, "\(c.name): reason")
        }
    }

    // MARK: Non-vector unit tests

    func testMinuteAccumulatorGroupsTwelveTicks() {
        var acc = MinuteAccumulator(samplesPerMinute: 12)
        var finished: [MinuteResult] = []
        for i in 0..<30 {
            if let m = acc.add(passed: i % 3 != 0, hr: 120, cadence: nil) { finished.append(m) }
        }
        XCTAssertEqual(finished.count, 2)
        XCTAssertEqual(finished[0].t, 12)
        XCTAssertEqual(finished[0].p, 8)
        XCTAssertEqual(finished[0].hr, 120)
        XCTAssertNil(finished[0].cad)
        XCTAssertEqual(acc.ticksInCurrentMinute, 6)
        XCTAssertEqual(acc.completed.count, 2)
    }

    func testRulesDecodeFillsDefaults() throws {
        let rules = try JSONDecoder().decode(Rules.self, from: Data(#"{"ratio":5}"#.utf8))
        XCTAssertEqual(rules.ratio, 5)
        XCTAssertEqual(rules.debitLimit, 60)
        XCTAssertNil(rules.maxBank)
    }

    func testPlayWindowParsing() {
        XCTAssertEqual(PlayWindow.minutes(from: "24:00"), 1440)
        XCTAssertEqual(PlayWindow.minutes(from: "07:30"), 450)
        XCTAssertNil(PlayWindow.minutes(from: "24:30"))
        XCTAssertNil(PlayWindow.minutes(from: "bad"))
    }
}
